+const envDecoderRowsX4 = "GO_PHERENCE_WHISPER_DECODER_ROWS_X4"
+
+// Existing AVX2 Sdotx4 has the same two accumulator chains and horizontal
+// reduction as Sdot for K divisible by16. Other ISAs/tails keep Sdot unchanged.
+func decoderRowsX4Enabled(inDim int) bool {
+	return os.Getenv(envDecoderRowsX4) == "1" && runtime.GOARCH == "amd64" && simdrt.HasSdotx4SIMD && simdrt.HasDotAsm && inDim > 0 && inDim%16 == 0
+}

